  + '      const nodeWidth = Math.max(textWidth + TEXT_PADDING, NODE_MIN_WIDTH);\n'
  + '      measuredWidths.set(node.id, nodeWidth);\n'
  + '    }\n'
  + '    setNodeWidths(measuredWidths);\n'
