  + '\n'
  + '  const layout = useMemo(() => {\n'
  + '    const g = new dagre.graphlib.Graph();\n'
  + '\n'
  + '    g.setGraph({\n'
  + '      rankdir: "LR",\n'
  + '      nodesep: NODESEP,\n'
  + '      ranksep: RANKSEP,\n'
  + '    });\n'
  + '\n'
