  + '};\n'
  + '\n'
  + 'Graph.displayName = "Graph";\n'
  + '\n'
  + 'type GraphEdgeProps = {\n'
  + '  points: Array<{ x: number; y: number }>;\n'
  + '  arrowheadId: string;\n'
  + '};\n'
  + '\n'
  + 'const GraphEdge: FC<GraphEdgeProps> = (props) => {\n'
  + '  const { points, arrowheadId } = props;\n'
  + '\n'
  + '  const theme = useTheme();\n'
  + '  const mode = useMode();\n'
  + '\n'
  + '  if (points.length !== 3) return null;\n'
  + '\n'
  + '  const [start, control, end] = points;\n'
